import type { Prayer } from "./prayerCategories";

export const NOVENA_PRAYERS_8: Prayer[] = [
  // NOVENA TO SAINT AUGUSTINE
  // novenaId: "novenas-saint-augustine"

  {
    id: "sa-np-1",
    novenaId: "novenas-saint-augustine",
    title: "Day 1 — Conversion of Heart",
    category: "novenas",
    day: 1,
    intention: "For a true and lasting conversion",
    text: `O God of mercy and power, who touched the heart of Saint Augustine and drew him from the depths of sin to the heights of sanctity, I come before You this day seeking a genuine conversion of my own heart. Like Augustine, I have wandered in the darkness of sin, enslaved by disordered desires and the illusions of a world that promises happiness but delivers emptiness. Yet Your grace is stronger than my weakness, and Your love is deeper than my sin. I ask You, through the intercession of Saint Augustine, to break the chains that bind me to my past failures and to set my feet upon the path of righteousness. Grant me the grace to weep over my sins as Augustine wept, to turn away from everything that separates me from You, and to begin anew with a heart that is contrite and humble. May this novena be the turning point of my life, the moment when I surrender completely to Your transforming grace and allow You to make all things new within me. Amen.`,
  },
  {
    id: "sa-np-2",
    novenaId: "novenas-saint-augustine",
    title: "Day 2 — The Restless Heart",
    category: "novenas",
    day: 2,
    intention: "To find rest in God alone",
    text: `O Eternal God, who created the human heart with an infinite capacity for Yourself, grant me through the intercession of Saint Augustine the grace to recognize that my heart is restless until it rests in You. I confess that I have sought satisfaction in created things — in pleasure, in ambition, in the approval of others — and each time I have been left more empty than before. Saint Augustine sought fulfillment in philosophy, in sensual pleasures, and in worldly honors, but he found true peace only when he surrendered his restless heart to Your embrace. Teach me to stop running from Yourself and to come to You with the same humility and longing that marked his conversion. May I understand that no earthly treasure can satisfy the hunger of my soul, and that only in You, O Lord, will I find the peace that surpasses all understanding. Let me hear Your voice calling me from the depths of my heart, drawing me ever closer to the source of all that is good, true, and beautiful. Amen.`,
  },
  {
    id: "sa-np-3",
    novenaId: "novenas-saint-augustine",
    title: "Day 3 — The Gift of Wisdom",
    category: "novenas",
    day: 3,
    intention: "To grow in divine wisdom",
    text: `O God of all wisdom, who revealed to Saint Augustine the depths of Your eternal truths and made him a Doctor of the Church, grant me through his intercession the gift of true wisdom that comes from above. I do not ask for the empty knowledge of the world, but for the living wisdom that begins with the fear of the Lord and leads to the understanding of Your holy will. Saint Augustine, who wrestled with heresy and error, who wrote the City of God and the Confessions, teaches me that true wisdom is not found in human reasoning alone but in the humble submission of the intellect to divine revelation. Illuminate my mind with the light of faith, that I may see all things through the lens of Your eternal truth. Grant me the wisdom to discern between what is of You and what is of the world, between what leads to salvation and what leads to perdition, between the fleeting pleasures of this life and the everlasting joy of heaven. May the wisdom of Saint Augustine guide me always in the ways of truth. Amen.`,
  },
  {
    id: "sa-np-4",
    novenaId: "novenas-saint-augustine",
    title: "Day 4 — The Power of Grace",
    category: "novenas",
    day: 4,
    intention: "To rely completely on God's grace",
    text: `O Lord Jesus Christ, Word made Flesh, who showered Your grace upon Saint Augustine and raised him from the miry clay of sin to the throne of episcopal authority, I humbly acknowledge my absolute dependence upon Your saving grace. I confess that without You I can do nothing — that every good impulse, every holy desire, every act of virtue comes from Your bountiful hand and not from my own merit. Saint Augustine, who once believed he could save himself through his own efforts, came to understand that it is You who seek us, You who convert us, You who sustain us, and You who bring us to glory. Free me from the heresy of Pelagianism that lurks in the pride of my heart — the temptation to believe that I can earn Your love or achieve salvation by my own works. May I cling to the cross of Christ as my only hope, trusting that Your grace is sufficient for me and that Your power is made perfect in weakness. Let me never boast in anything except the infinite mercy of God who saves sinners. Amen.`,
  },
  {
    id: "sa-np-5",
    novenaId: "novenas-saint-augustine",
    title: "Day 5 — Love of Sacred Scripture",
    category: "novenas",
    day: 5,
    intention: "To study and live the Word of God",
    text: `O God, who spoke through the prophets and has given us the Holy Scriptures as a lamp unto our feet and a light unto our path, grant me through the intercession of Saint Augustine a burning love for Your sacred Word. It was the voice of a child chanting "Tolle lege, tolle lege" — Take up and read — that prompted Augustine to open the epistle of Saint Paul and discover the grace that would change his life forever. Grant me the same reverence for Holy Scripture that animated the great Doctor of the Church, who immersed himself in the Psalms, the Gospels, and the epistles with a hunger for truth that could never be satisfied. May I not merely read Your Word but meditate upon it day and night, allowing its truth to penetrate the deepest recesses of my heart and transform my mind. Help me to study Scripture with humility, to accept its teachings without reservation, and to live according to its precepts with unwavering fidelity. May the Word of God be the foundation of my life and the source of my daily strength. Amen.`,
  },
  {
    id: "sa-np-6",
    novenaId: "novenas-saint-augustine",
    title: "Day 6 — Detachment from Worldly Things",
    category: "novenas",
    day: 6,
    intention: "To let go of earthly attachments",
    text: `O Heavenly Father, who called Saint Augustine to leave behind the pleasures of the world and to embrace the poverty of Christ, grant me through his intercession the grace of holy detachment from all that is passing and temporal. I confess that my heart is still attached to possessions, to status, to comfort, and to the fleeting approval of those who do not know You. Like Augustine, who renounced a brilliant academic career and the pleasures of Roman society to follow the call of Christ, teach me to count all things as loss compared to the surpassing worth of knowing Jesus as Lord. Free me from the tyranny of material things, from the illusion that wealth can purchase happiness, and from the fear of poverty that keeps me clinging to what I should freely give. Grant me the courage to simplify my life, to share my resources with those in need, and to store up treasures in heaven where neither moth nor rust consumes. May I learn that true freedom is found not in having more but in needing less, and that the richest person is the one who desires nothing but God. Amen.`,
  },
  {
    id: "sa-np-7",
    novenaId: "novenas-saint-augustine",
    title: "Day 7 — The City of God",
    category: "novenas",
    day: 7,
    intention: "To live as a citizen of heaven",
    text: `O Lord of all creation, who revealed to Saint Augustine the two cities — the City of God built on love of You, and the City of Man built on love of self — grant me through his intercession the grace to live always as a citizen of Your heavenly kingdom. I confess that I am too often conformed to the values of this passing world, distracted by its entertainments, troubled by its conflicts, and deceived by its empty promises. Saint Augustine, who wrote his great work in the shadow of the fall of Rome, teaches me that every earthly empire will crumble, every human achievement will fade, but the City of God stands firm forever. Help me to set my mind on things above, where Christ is seated at the right hand of the Father, and to live each day in anticipation of that eternal home where there will be no more death, no more sorrow, no more crying, and no more pain. May my priorities reflect my heavenly citizenship, and may my actions testify that I belong to a kingdom that cannot be shaken. Amen.`,
  },
  {
    id: "sa-np-8",
    novenaId: "novenas-saint-augustine",
    title: "Day 8 — Charity and the Love of God",
    category: "novenas",
    day: 8,
    intention: "To love God and neighbor perfectly",
    text: `O God who is Love itself, who poured into the heart of Saint Augustine a burning charity that transformed his life and his world, kindle in my heart the same divine love that animated the great Doctor of grace. Saint Augustine taught that all virtue is rooted in love — love of God above all things and love of neighbor for God's sake. He also taught that sin is disordered love, the love of lesser things in place of the Supreme Good. Grant me the grace to order my loves rightly, to love You with all my heart, soul, mind, and strength, and to love my neighbor as myself for Your sake. Help me to see Your image in every human face, to serve You in the poor, the sick, the lonely, and the forgotten, and to extend the same mercy to others that You have so abundantly extended to me. May the love of God so fill my heart that it overflows in acts of kindness, forgiveness, and self-sacrifice, making me a living sign of Your kingdom in a world that desperately needs Your healing love. Amen.`,
  },
  {
    id: "sa-np-9",
    novenaId: "novenas-saint-augustine",
    title: "Day 9 — Eternal Life and Hope",
    category: "novenas",
    day: 9,
    intention: "To persevere in hope of heaven",
    text: `O God of hope and glory, who drew Saint Augustine from the darkness of error to the light of eternal truth, grant me through his intercession the grace to persevere in faith, hope, and charity until the day of my death. I believe in the resurrection of the body and the life everlasting, and I trust that the same God who converted the great Augustine will sustain me in my own journey toward heaven. Saint Augustine, who died at Hippo in the year 430 with the Psalms of David on his lips, teaches me that the Christian life is a pilgrimage — a journey through the valley of tears toward the promised land of eternal blessedness. Strengthen my hope when trials overwhelm me, when temptation assails me, and when the darkness of doubt clouds my mind. Grant me the grace to finish the race, to keep the faith, and to hear at the end of my days the words of the Master: "Well done, good and faithful servant, enter into the joy of your Lord." Through the intercession of Saint Augustine, may I one day join the blessed in heaven, praising the Father, the Son, and the Holy Spirit for all eternity. Amen.`,
  },

  // NOVENA TO SAINT CATHERINE OF SIENA
  // novenaId: "novenas-saint-catherine-siena"

  {
    id: "scs-np-1",
    novenaId: "novenas-saint-catherine-siena",
    title: "Day 1 — Courage in Faith",
    category: "novenas",
    day: 1,
    intention: "To be bold in professing the faith",
    text: `O God, who raised up Saint Catherine of Siena as a fearless witness to the truth of the Gospel, grant me through her intercession the courage to profess my faith without hesitation or compromise. I confess that at times I am afraid to speak the name of Jesus, to defend the teachings of Holy Mother Church, or to stand for what is right when the world mocks those who believe. Saint Catherine, though a young woman of humble origin, confronted popes and princes with the boldness of the Holy Spirit, never wavering in her fidelity to Christ and His Church. Grant me this same holy audacity that I may be unashamed of the Gospel, which is the power of God unto salvation. Help me to recognize that the truth of Christ is worth any sacrifice, any suffering, and any cost, and that those who speak the truth in love will always be guided by the Holy Spirit. May I never trade the eternal truth for the fleeting approval of the world. Amen.`,
  },
  {
    id: "scs-np-2",
    novenaId: "novenas-saint-catherine-siena",
    title: "Day 2 — Holy Dialogue with God",
    category: "novenas",
    day: 2,
    intention: "To deepen prayer and conversation with God",
    text: `O Lord Jesus Christ, who spoke intimately with Saint Catherine of Siena, revealing to her the depths of Your Sacred Heart and entrusting her with messages for the Church, grant me through her intercession the grace of deep and sustaining prayer. I confess that my prayer life is often shallow, distracted, and infrequent, and that I do not make sufficient time for intimate conversation with You. Saint Catherine spent hours in contemplation, conversing with Christ as with a friend, and from those holy conversations she received wisdom and strength that transformed the Church. Teach me to pray with greater depth, to listen for Your voice in the silence of my heart, and to speak to You with the same candor and affection that marked the dialogue of this remarkable saint. May I learn to retreat from the noise of the world and enter into the "cell of self-knowledge" where You dwell, where You speak words of peace, and where You prepare the soul for union with Your divine will. Grant me the grace to make prayer the foundation of my entire life. Amen.`,
  },
  {
    id: "scs-np-3",
    novenaId: "novenas-saint-catherine-siena",
    title: "Day 3 — The Blood of Christ",
    category: "novenas",
    day: 3,
    intention: "To reverence the saving Passion of Jesus",
    text: `O Precious Blood of Jesus Christ, fountain of redemption and source of all grace, I venerate You this day through the intercession of Saint Catherine of Siena, who bore upon her body the sacred stigmata of Christ's Passion. You, O Blood of Christ, cleanse us from all sin, heal our wounds, reconcile us to the Father, and give us access to the throne of divine mercy. Saint Catherine, who experienced in her own flesh the sufferings of the Lord, teaches me to contemplate the Passion with profound gratitude and reverent love. Grant me the grace to unite my own small sufferings to the infinite sacrifice of Calvary, and to offer them for the conversion of sinners and the intentions of the Holy Father. May the precious Blood that flowed from the hands, the feet, and the side of Jesus be my constant meditation, my hope in times of trial, and my confidence on the day of judgment. Let me never take for granted the tremendous price that was paid for my redemption. Amen.`,
  },
  {
    id: "scs-np-4",
    novenaId: "novenas-saint-catherine-siena",
    title: "Day 4 — Dialogue and Reconciliation",
    category: "novenas",
    day: 4,
    intention: "To be an instrument of peace and unity",
    text: `O Prince of Peace, who sent Saint Catherine of Siena as an ambassador of reconciliation to the warring factions of Italy and to the divided Church, grant me through her intercession the grace to be an instrument of peace and dialogue in my own sphere of influence. I confess that I too often avoid difficult conversations, hold grudges against those who have wronged me, and contribute to division rather than unity through my words and actions. Saint Catherine traveled hundreds of miles, risked her health, and endured misunderstanding to bring estranged parties to the table of reconciliation. Grant me the same selfless dedication to the cause of peace, the willingness to speak the truth in love, and the humility to seek forgiveness when I have caused offense. Help me to see in every human person, even those who oppose me, a brother or sister for whom Christ died, and to treat them accordingly. May I become a peacemaker after the heart of Jesus, who said: "Blessed are the peacemakers, for they shall be called children of God." Amen.`,
  },
  {
    id: "scs-np-5",
    novenaId: "novenas-saint-catherine-siena",
    title: "Day 5 — Church Unity",
    category: "novenas",
    day: 5,
    intention: "For the unity of the Church",
    text: `O Good Shepherd, who gathered Saint Catherine to Yourself and sent her to heal the divisions within Your Church, grant me through her intercession the grace to work tirelessly for the unity of all Christians. I confess that I have often been indifferent to the scandal of Christian division, failing to pray for the restoration of that visible unity for which Your Son prayed before His Passion. Saint Catherine pleaded with the Pope to return to Rome and to exercise his authority for the good of the faithful, knowing that the unity of the Church was essential for the salvation of souls. Grant me a passionate love for Holy Mother Church, a zealous commitment to her teaching, and a sincere desire for the reconciliation of all who bear the name of Christ. Help me to understand that division among Christians weakens the witness of the Gospel and hinders the work of evangelization, and to do whatever I can to promote understanding, charity, and communion among the various Christian communities. May the prayer of Jesus — "that they may all be one" — echo in my heart and guide my actions every day. Amen.`,
  },
  {
    id: "scs-np-6",
    novenaId: "novenas-saint-catherine-siena",
    title: "Day 6 — Purity of Heart",
    category: "novenas",
    day: 6,
    intention: "To maintain purity in thought and deed",
    text: `O Jesus, pure and immaculate, who granted to Saint Catherine the grace of virginal purity both in body and in soul, grant me through her intercession the grace of heart purity that I may see You clearly and love You perfectly. I confess that my thoughts are often impure, my desires disordered, and my gaze distracted by the passing pleasures of the flesh. Saint Catherine, who was espoused to Christ in a mystical marriage and who guarded her heart with the utmost vigilance, teaches me that purity is not merely the absence of sin but the presence of a consuming love for God that leaves no room for lesser attachments. Cleanse my mind of every impure thought, purify my eyes from every immodest glance, and sanctify my heart with the fire of Your divine love. Grant me the strength to resist the temptations of the flesh, the wisdom to avoid the occasions of sin, and the grace to grow daily in holiness of life. May I become a temple of the Holy Spirit, pure in body and soul, fit for the eternal union with You that is the destiny of every baptized Christian. Amen.`,
  },
  {
    id: "scs-np-7",
    novenaId: "novenas-saint-catherine-siena",
    title: "Day 7 — Obedience to the Church",
    category: "novenas",
    day: 7,
    intention: "To submit to the teaching authority of the Church",
    text: `O Lord Jesus Christ, who established Your Church upon the rock of Peter and promised that the gates of hell would not prevail against it, grant me through the intercession of Saint Catherine of Siena the grace of filial obedience to the teaching authority of Holy Mother Church. I confess that I have sometimes been tempted to pick and choose which teachings to accept, to judge the Church's leaders by my own standards, and to substitute my own judgment for the wisdom of two thousand years of sacred Tradition. Saint Catherine, though she did not hesitate to correct popes when they strayed, always did so with profound reverence for the authority of the See of Peter and unwavering loyalty to the Magisterium. Grant me the humility to submit my intellect to the teachings of the Church, the docility to be formed by her wisdom, and the courage to defend her teachings even when they are unpopular or misunderstood. Help me to understand that obedience to the Church is not a sign of weakness but of genuine faith in Christ, who promised to remain with His Church until the end of time. Amen.`,
  },
  {
    id: "scs-np-8",
    novenaId: "novenas-saint-catherine-siena",
    title: "Day 8 — Concern for the Dying",
    category: "novenas",
    day: 8,
    intention: "For the grace of a holy death",
    text: `O God of mercy and compassion, who granted to Saint Catherine a profound concern for the salvation of souls and the preparation for death, grant me through her intercession the grace to prepare myself worthily for the moment when I must appear before Your judgment seat. I confess that I often live as though I will never die, neglecting the preparation of my soul and procrastinating in the work of conversion. Saint Catherine devoted herself to the care of the sick and the dying, understanding that the last moments of earthly life are of infinite importance for eternity. Grant me the wisdom to live each day as though it were my last, to keep my soul in a state of grace through frequent Confession and the worthy reception of Holy Communion, and to settle all earthly affairs so that I may depart this world with peace of mind and confidence in Your mercy. When my final hour approaches, may I receive the last rites of Holy Church, may I unite my suffering to the Passion of Christ, and may I commend my soul into Your hands with the same trust that animated Saint Catherine at the hour of her death. Amen.`,
  },
  {
    id: "scs-np-9",
    novenaId: "novenas-saint-catherine-siena",
    title: "Day 9 — Complete Gift to God",
    category: "novenas",
    day: 9,
    intention: "To consecrate one's life entirely to God",
    text: `O Lord Jesus Christ, who revealed to Saint Catherine the fire of divine love that consumed her entire being, grant me through her intercession the grace of complete self-offering that I may belong to You alone without reservation. I consecrate to You this day my body, my soul, my mind, my heart, my hands, my feet, my voice, my eyes — every part of me that You have created and redeemed by Your precious Blood. Like Saint Catherine, who held nothing back from You but gave herself entirely to Your service, I desire to become an instrument of Your love in the world, a living sacrifice acceptable and pleasing to God. Use me as You will, send me where You wish, grant me what You desire, and take from me whatever separates me from perfect union with Your heart. I place my life in Your sacred hands and trust that You will guide me according to Your most holy will. Through the intercession of Saint Catherine of Siena, may I become a beacon of Your truth, a vessel of Your grace, and a faithful servant of Your Church until the day I am called to the eternal kingdom where You live and reign with the Father and the Holy Spirit, one God, forever and ever. Amen.`,
  },

  // NOVENA TO SAINT DOMINIC
  // novenaId: "novenas-saint-dominic"

  {
    id: "sdo-np-1",
    novenaId: "novenas-saint-dominic",
    title: "Day 1 — The Preaching of Truth",
    category: "novenas",
    day: 1,
    intention: "To proclaim the truth of the Gospel",
    text: `O God of truth, who raised up Saint Dominic to preach Your word with clarity, charity, and power, grant me through his intercession the grace to speak the truth in love in every circumstance of my life. I confess that I am often afraid to proclaim the Gospel, uncertain of how my words will be received, and tempted to remain silent rather than risk confrontation. Saint Dominic, the "Hound of Heaven," pursued souls with a burning zeal that would not be satisfied until every creature knew and loved the truth of Jesus Christ. Grant me this same apostolic fervor that I may never be content to live a private faith but will always be ready to give an account of the hope that is in me, with gentleness and reverence. Help me to understand that the truth of Christ is not a weapon to be used against others but a gift to be shared for their salvation, and that the greatest act of love is to help another person know the God who made them and died for them. May the Holy Spirit fill my mouth with words of fire, and may I never be ashamed of the Gospel, which is the power of God for the salvation of all who believe. Amen.`,
  },
  {
    id: "sdo-np-2",
    novenaId: "novenas-saint-dominic",
    title: "Day 2 — The Holy Rosary",
    category: "novenas",
    day: 2,
    intention: "To develop a deep devotion to the Rosary",
    text: `O Blessed Virgin Mary, Queen of the Most Holy Rosary, who entrusted the sacred beads to Saint Dominic as a powerful weapon against heresy and sin, grant me through his intercession the grace of unwavering devotion to the Holy Rosary. I confess that I have often neglected this heavenly prayer, substituting other devotions or simply failing to make time for the meditation upon the mysteries of salvation that the Rosary provides. Saint Dominic, who received the Rosary from Your Immaculate hands in the vision at Toulouse, used it to convert thousands of souls from the darkness of the Albigensian heresy to the light of Catholic truth. Grant me the grace to pray the Rosary daily, not as a mere repetition of words but as a deep contemplation of the life, death, and glory of Jesus Christ through the eyes of His Blessed Mother. May each bead draw me closer to the heart of Jesus, and may the mysteries I contemplate transform my life and make me an instrument of conversion for others. O Mary, conceived without sin, pray for us who have recourse to you. Amen.`,
  },
  {
    id: "sdo-np-3",
    novenaId: "novenas-saint-dominic",
    title: "Day 3 — Study and Learning",
    category: "novenas",
    day: 3,
    intention: "To grow in knowledge for the service of God",
    text: `O God of all knowledge, who blessed Saint Dominic with extraordinary learning and made him a master of sacred theology, grant me through his intercession the grace to pursue knowledge not for my own glory but for the greater service of Your kingdom. I confess that I have often been lazy in my studies, satisfied with superficial understanding, and failed to use the intellect You have given me for the advancement of Your truth. Saint Dominic, who founded the Order of Preachers to bring the light of learning to the Church, teaches me that study is a form of prayer and that the mind must be trained to defend the faith and to penetrate the depths of divine revelation. Grant me the discipline to study diligently, the humility to learn from others, and the wisdom to integrate all knowledge into a deeper love for You and Your Church. Help me to understand that ignorance of the faith is not an excuse but a danger, and that every Christian is called to grow in understanding of the truth that has been revealed. May my study always be directed toward the salvation of souls and the glory of Your name. Amen.`,
  },
  {
    id: "sdo-np-4",
    novenaId: "novenas-saint-dominic",
    title: "Day 4 — Poverty and Simplicity",
    category: "novenas",
    day: 4,
    intention: "To embrace holy poverty",
    text: `O Lord Jesus Christ, who chose to be born in poverty, who lived as a homeless preacher, and who died on the Cross stripped of everything, grant me through the intercession of Saint Dominic the grace of holy poverty and radical simplicity. I confess that I am attached to material possessions, that I find my security in what I own, and that I am often more concerned with accumulating wealth than with storing up treasures in heaven. Saint Dominic, who gave away everything he had, who was so poor that he literally had nothing to bequeath to his friars except the holy Gospel, teaches me that true freedom is found in detachment from created things. Grant me the courage to live simply, to share generously, to trust in divine providence, and to resist the consumer culture that surrounds me. Help me to understand that the poor are not an embarrassment to be avoided but Christ to whom I must minister, and that in serving them I serve You. May I become poor in spirit like Saint Dominic, rich only in the treasures of faith, hope, and charity that no earthly power can take away. Amen.`,
  },
  {
    id: "sdo-np-5",
    novenaId: "novenas-saint-dominic",
    title: "Day 5 — Compassion for Sinners",
    category: "novenas",
    day: 5,
    intention: "To love sinners as Christ loves them",
    text: `O Merciful Savior, who wept over the city of Jerusalem and who desired that none should perish, grant me through the intercession of Saint Dominic the grace to love sinners with the same tender compassion that characterized Your own earthly ministry. I confess that I am often judgmental toward those who fall into sin, impatient with their weaknesses, and quick to condemn rather than to intercede. Saint Dominic, who traveled through towns and villages preaching with tears in his eyes for the conversion of the wicked, teaches me that the soul of the sinner is more precious to God than all the treasures of the world. Grant me the grace to see every sinner as a beloved child of God for whom Christ died, and to approach them not with self-righteousness but with humility, knowing that I too am a sinner in constant need of mercy. Help me to pray for the conversion of those who have strayed from the faith, to offer sacrifices for their return, and to trust that no soul is beyond the reach of divine grace. May I become, like Saint Dominic, a tireless laborer in the vineyard of the Lord, working for the salvation of every soul. Amen.`,
  },
  {
    id: "sdo-np-6",
    novenaId: "novenas-saint-dominic",
    title: "Day 6 — Fidelity to the Eucharist",
    category: "novenas",
    day: 6,
    intention: "To deepen love for the Blessed Sacrament",
    text: `O Jesus Christ, true God and true Man, really present in the Most Holy Eucharist under the appearances of bread and wine, grant me through the intercession of Saint Dominic a profound love and reverence for this ineffable sacrament of Your love. I confess that I have often received You in Holy Communion with little preparation, little attention, and little gratitude for the tremendous gift of Your Body, Blood, Soul, and Divinity. Saint Dominic, who was so devoted to the Blessed Sacrament that he spent entire nights in adoration, who celebrated Mass with tears streaming down his face, and who received miraculous graces from this heavenly food, teaches me to recognize Jesus Christ in the consecrated Host with the same faith and love that animated his own Eucharistic devotion. Grant me the grace to prepare myself worthily for each reception of Holy Communion, to remain in thanksgiving after Mass, and to visit You often in the Blessed Sacrament. May the Eucharist become the source and summit of my entire spiritual life, nourishing my soul, strengthening my virtue, and drawing me ever closer to the heart of the Good Shepherd. Amen.`,
  },
  {
    id: "sdo-np-7",
    novenaId: "novenas-saint-dominic",
    title: "Day 7 — Community and Brotherhood",
    category: "novenas",
    day: 7,
    intention: "To live in Christian communion with others",
    text: `O Lord Jesus Christ, who gathered Saint Dominic into a brotherhood of preachers united by the vows of poverty, chastity, and obedience, grant me through his intercession the grace to live in genuine Christian community with my brothers and sisters in the faith. I confess that I am often solitary in my spiritual life, that I fail to support others in their journey toward God, and that I do not always value the gifts that each member of the Body of Christ brings to the community. Saint Dominic, who gathered around himself a family of friars, nuns, and laypeople united by a common charism and a common mission, teaches me that holiness is not achieved in isolation but in communion with others who share the same faith and the same hope. Grant me the grace to be a loyal friend, a supportive community member, a generous sharer of spiritual gifts, and a faithful servant of the Church in my local parish and beyond. Help me to overcome the selfish individualism that isolates me from others and to embrace the biblical vision of the early Church, where all things were held in common and the love of Christ bound every heart in unity and peace. Amen.`,
  },
  {
    id: "sdo-np-8",
    novenaId: "novenas-saint-dominic",
    title: "Day 8 — The Conversion of Heretics",
    category: "novenas",
    day: 8,
    intention: "For the return of those who have left the faith",
    text: `O God of truth, who sent Saint Dominic to combat the heresies of his time and to bring thousands back to the fullness of Catholic faith, grant me through his intercession the grace to be an instrument of conversion for those who have strayed from the truths of Holy Mother Church. I pray in particular for those who have been deceived by false teachings, who have embraced error in the name of modernity, or who have simply drifted away from the practice of the faith through indifference or scandal. Saint Dominic, who debated with heretics, who prayed for their conversion, and who loved them enough to tell them the truth even when it was unwelcome, teaches me that the greatest charity is to help another person find the truth that will set them free. Grant me the wisdom to know how to speak to those who are confused, the patience to listen to their objections, the charity to respect their dignity, and the courage to proclaim the fullness of Catholic truth without apology. May the Holy Spirit guide my words and touch the hearts of those who hear, that many who have wandered from the fold may return to the safe harbor of the Church. Amen.`,
  },
  {
    id: "sdo-np-9",
    novenaId: "novenas-saint-dominic",
    title: "Day 9 — Perseverance in Mission",
    category: "novenas",
    day: 9,
    intention: "To persevere in the mission God has given",
    text: `O God of all perseverance, who sustained Saint Dominic in his mission of preaching and teaching throughout his entire life, granting him the grace to persevere in holy labor until his death, grant me through his intercession the grace to remain faithful to the mission You have entrusted to me. I confess that I am often tempted to discouragement, that I lose heart when my efforts seem to bear no fruit, and that I am tempted to give up when the work becomes difficult or the results are disappointing. Saint Dominic, who walked barefoot across Europe, who slept on the ground, who ate only what was given to him, and who preached with tireless energy for the salvation of souls, teaches me that perseverance in the apostolate is a gift of God that must be sought through prayer, sustained by sacrifice, and confirmed by obedience. Grant me the grace to continue the work of evangelization in my own corner of the world, regardless of the obstacles, the opposition, or the apparent lack of success. Help me to remember that the results belong to God and that my only responsibility is to be faithful to the mission I have received. Through the intercession of Saint Dominic, may I run the race to the finish, keep the faith, and hear the Master's welcome at the end of my days. Amen.`,
  },

  // NOVENA TO SAINT ELIZABETH OF HUNGARY
  // novenaId: "novenas-saint-elizabeth"

  {
    id: "seh-np-1",
    novenaId: "novenas-saint-elizabeth",
    title: "Day 1 — Charity for the Poor",
    category: "novenas",
    day: 1,
    intention: "To love and serve the poor",
    text: `O God of mercy and compassion, who raised up Saint Elizabeth of Hungary as a model of charity for the poor and the suffering, grant me through her intercession the grace to love the poor as Christ loves them — not with a distant, sentimental affection but with a practical, sacrificial love that gives until it hurts. I confess that I have often turned away from the needs of the poor, making excuses for my lack of generosity, and failing to see in the face of the beggar the face of Christ Himself. Saint Elizabeth, who gave away her food, her clothing, and her wealth to those in need, who built hospitals and fed the hungry, and who spent herself entirely in the service of the least of her brothers and sisters, teaches me that charity is the soul of Christian life and the proof of our love for God. Grant me the grace to open my eyes to the needs around me, to open my hands in generosity, and to open my heart in compassion. Help me to understand that what I do for the poor I do for Christ, and that every act of charity, no matter how small, is precious in the eyes of the Lord. Amen.`,
  },
  {
    id: "seh-np-2",
    novenaId: "novenas-saint-elizabeth",
    title: "Day 2 — Humility in Service",
    category: "novenas",
    day: 2,
    intention: "To serve others with a humble heart",
    text: `O Jesus, meek and humble of heart, who taught us that the greatest in the Kingdom of Heaven is the one who makes himself the least, grant me through the intercession of Saint Elizabeth the grace of genuine humility that seeks not recognition but simply the good of the other. I confess that I am often motivated by pride, that I seek acknowledgment for my good deeds, and that I am tempted to serve others in order to be seen and praised by them. Saint Elizabeth, a princess and queen who voluntarily chose to wash the feet of beggars and to serve the sick with her own hands, teaches me that true greatness lies not in titles or honors but in the humble service of others. Strip away my pride, my vanity, and my desire for human approval, and replace them with the holy humility that characterized the life of the Blessed Virgin Mary, who sang: "He has cast down the mighty from their thrones and has lifted up the lowly." Grant me the grace to serve without seeking thanks, to give without expecting anything in return, and to find my joy in the knowledge that God sees what is hidden from human eyes and will reward accordingly. Amen.`,
  },
  {
    id: "seh-np-3",
    novenaId: "novenas-saint-elizabeth",
    title: "Day 3 — The Roses of Charity",
    category: "novenas",
    day: 3,
    intention: "To bring beauty and joy through acts of love",
    text: `O God of beauty and wonder, who performed the miracle of the roses through the hands of Saint Elizabeth, transforming the bread she carried for the poor into a cascade of heavenly flowers, grant me through her intercession the grace to bring beauty and joy into the lives of others through acts of selfless charity. I confess that I often see service to others as a burden rather than a privilege, as an obligation rather than an opportunity to participate in the divine work of love. Saint Elizabeth, who risked scandal and ridicule to bring food to the poor, and whose bread was transformed into roses as a sign that God blesses and multiplies every act of charity, teaches me that nothing done for love of God and neighbor is ever wasted or forgotten. Grant me the grace to approach every opportunity for service with enthusiasm and joy, trusting that God will bless even my imperfect efforts and transform them into something far greater than I could have imagined. May the roses of charity bloom in my life, bringing fragrance and beauty to a world that desperately needs the touch of divine love. Amen.`,
  },
  {
    id: "seh-np-4",
    novenaId: "novenas-saint-elizabeth",
    title: "Day 4 — Dedication to the Sick",
    category: "novenas",
    day: 4,
    intention: "To care for those who are ill",
    text: `O Lord Jesus Christ, Divine Physician, who healed the sick by Your word and by Your touch, and who established the works of mercy as pathways to holiness, grant me through the intercession of Saint Elizabeth the grace to care for the sick and suffering with patience, tenderness, and unwavering dedication. I confess that I am often uncomfortable around illness, that I avoid the suffering because I do not know what to say or do, and that I fail to recognize the face of Christ in the face of the sick. Saint Elizabeth, who founded hospitals, who nursed the plague-stricken with her own hands, and who regarded the care of the sick as a sacred trust, teaches me that the sick are among the most vulnerable members of the Body of Christ and that in serving them I serve the Lord Himself. Grant me the grace to overcome my fear of suffering, to approach the sick with compassion and skill, and to offer my own health and strength for the healing of others. Help me to understand that the sick have a special proximity to the Passion of Christ and that in accompanying them I am walking the way of the Cross with my Savior. Amen.`,
  },
  {
    id: "seh-np-5",
    novenaId: "novenas-saint-elizabeth",
    title: "Day 5 — Consecration of Marriage",
    category: "novenas",
    day: 5,
    intention: "To sanctify the married state",
    text: `O God of holy love, who blessed the marriage of Saint Elizabeth and her husband Louis with faithfulness, charity, and mutual sanctification, grant me through her intercession the grace to live my own state of life — whether married, single, or consecrated — with holiness and devotion. I confess that I have often failed to see the spiritual potential of my daily circumstances, that I have neglected the opportunities for sanctification that surround me, and that I have not always treated the people in my life with the reverence they deserve as beloved children of God. Saint Elizabeth, who fulfilled her duties as wife, mother, and queen with extraordinary grace, and who sanctified every aspect of her domestic life through the love of God, teaches me that holiness is not reserved for those who withdraw from the world but is the calling of every baptized Christian in whatever state of life they find themselves. Grant me the grace to fulfill my duties with fidelity, to love the people in my life with generosity, and to transform my daily work into a prayer that rises like incense before the throne of God. Amen.`,
  },
  {
    id: "seh-np-6",
    novenaId: "novenas-saint-elizabeth",
    title: "Day 6 — Patience in Affliction",
    category: "novenas",
    day: 6,
    intention: "To bear suffering with patience and trust",
    text: `O God of all consolation, who sustained Saint Elizabeth through the trials of widowhood, poverty, slander, and exile, grant me through her intercession the grace of holy patience when affliction comes upon me. I confess that I am often impatient in suffering, that I complain against Your providence, and that I fail to unite my trials to the Cross of Christ for the redemption of the world. Saint Elizabeth, who was driven from her own castle by her in-laws, who wandered homeless through the countryside, and who endured every hardship with a serene trust in God's plan, teaches me that suffering is not meaningless but is a participation in the redemptive work of Jesus Christ. Grant me the grace to accept my crosses with courage, to offer them for the conversion of sinners and the relief of the holy souls, and to trust that God is working all things together for good for those who love Him. Help me to remember that this world is not my final home and that the sufferings of the present time are not worth comparing with the glory that will be revealed in us. Amen.`,
  },
  {
    id: "seh-np-7",
    novenaId: "novenas-saint-elizabeth",
    title: "Day 7 — Generosity and Self-Giving",
    category: "novenas",
    day: 7,
    intention: "To give of myself without reservation",
    text: `O generous God, who gave to Saint Elizabeth the spirit of radical generosity that enabled her to give away everything she possessed for the love of You and the service of the poor, grant me through her intercession the grace of unstinting generosity that holds nothing back from Your service. I confess that I am often calculating in my charity, that I give only what is convenient, and that I reserve for myself far more than I need while others go without. Saint Elizabeth, who gave away her royal jewels, her clothing, and even the food from her own table, and who considered herself rich only when she had given everything away, teaches me that generosity is not measured by the amount given but by the sacrifice involved. Grant me the grace to open my hands, my heart, and my resources to those in need, trusting that You will provide for all my own needs according to Your riches in glory. Help me to understand that the greatest poverty is not the lack of material things but the refusal to share what I have been given, and that the greatest wealth is the treasure of a generous heart that mirrors the generosity of God Himself. Amen.`,
  },
  {
    id: "seh-np-8",
    novenaId: "novenas-saint-elizabeth",
    title: "Day 8 — Trust in Divine Providence",
    category: "novenas",
    day: 8,
    intention: "To trust completely in God's care",
    text: `O Heavenly Father, who clothed the lilies of the field and fed the birds of the air, and who provided for Saint Elizabeth even when she gave away everything she had, grant me through her intercession the grace of complete trust in Your divine providence. I confess that I am often anxious about material things — about food, clothing, shelter, and financial security — and that I place more confidence in my own efforts than in Your loving care. Saint Elizabeth, who gave away her possessions with reckless abandon and found that God always provided for her needs through unexpected sources, teaches me that the one who loses his life for Christ's sake will find it, and that the one who gives generously will receive in greater measure. Free me from the fear of poverty, from the tyranny of acquisitiveness, and from the illusion that my security depends on what I possess rather than on the God who sustains me at every moment. Grant me the faith to trust that You know what I need before I ask, that You will never allow me to lack what is truly necessary, and that the treasures I store in heaven through acts of charity will be waiting for me when I arrive at my eternal home. Amen.`,
  },
  {
    id: "seh-np-9",
    novenaId: "novenas-saint-elizabeth",
    title: "Day 9 — Intercession for the World",
    category: "novenas",
    day: 9,
    intention: "To pray for the needs of the whole world",
    text: `O God of all the earth, who gave to Saint Elizabeth a heart that embraced the whole world in its charity, grant me through her intercession the grace to pray for the needs of all people, not just those who are near and dear to me. I confess that my prayers are often selfish, focused on my own needs and desires, and that I fail to intercede for the poor, the suffering, the persecuted, and the forgotten members of the human family. Saint Elizabeth, who prayed for the whole world, who loved the stranger as her own child, and who saw in every person the image of God, teaches me that the love of God knows no boundaries and that the charity of Christ extends to every corner of the globe. Grant me the grace to widen the circle of my prayers to include all peoples, all nations, all religions, and all those who are in any way afflicted or distressed. Help me to remember that we are all brothers and sisters under the fatherhood of God, and that the suffering of one is the concern of all. Through the intercession of Saint Elizabeth of Hungary, may God's mercy and peace descend upon the whole earth, and may every human heart come to know the love of the Father, the Son, and the Holy Spirit. Amen.`,
  },

  // NOVENA TO SAINT MARY GORETTI
  // novenaId: "novenas-saint-mary-goretti"

  {
    id: "smg-np-1",
    novenaId: "novenas-saint-mary-goretti",
    title: "Day 1 — Purity of Heart",
    category: "novenas",
    day: 1,
    intention: "To guard the purity of one's heart",
    text: `O Jesus, pure and immaculate, who raised up Saint Mary Goretti as a lily of purity in a world that was hostile to virtue, grant me through her intercession the grace to guard the purity of my heart, my eyes, and my thoughts. I confess that I have been careless in protecting my innocence, that I have allowed impure thoughts to enter my mind, and that I have not always fled from the occasions of sin that endanger my soul. Saint Mary Goretti, who preferred death rather than to surrender her purity to her attacker, teaches me that the body is a temple of the Holy Spirit and that purity is not an outdated virtue but the gateway to a deeper knowledge and love of God. Grant me the grace to be vigilant in guarding my senses, to avoid the media and the situations that arouse disordered desires, and to cultivate a love for chastity that will make me strong in the face of temptation. May I learn from Saint Mary Goretti that true freedom is found not in the license of the flesh but in the mastery of self that comes from the grace of God and the practice of virtue. Amen.`,
  },
  {
    id: "smg-np-2",
    novenaId: "novenas-saint-mary-goretti",
    title: "Day 2 — Forgiveness of Enemies",
    category: "novenas",
    day: 2,
    intention: "To forgive those who wrong us",
    text: `O Lord Jesus Christ, who from the Cross prayed: "Father, forgive them, for they know not what they do," grant me through the intercession of Saint Mary Goretti the grace to forgive completely and from the heart every person who has wronged, harmed, or offended me. I confess that I harbor resentment, that I nurse grudges, and that I find it difficult to release the pain that others have caused me. Saint Mary Goretti, who forgave her murderer Alessandro Serenelli with her dying breath and who appeared to him in a vision to assure him of her forgiveness, demonstrates that the love of Christ can transform even the most hardened heart. Grant me the grace to let go of my anger, my bitterness, and my desire for revenge, and to replace them with a genuine desire for the salvation of those who have hurt me. Help me to understand that forgiveness is not a feeling but a decision of the will, that it does not require the reconciliation of the relationship but the release of the debt, and that in forgiving others I open my own heart to receive the forgiveness of God. Amen.`,
  },
  {
    id: "smg-np-3",
    novenaId: "novenas-saint-mary-goretti",
    title: "Day 3 — Courage in Trials",
    category: "novenas",
    day: 3,
    intention: "To be brave in the face of suffering",
    text: `O God of courage and strength, who sustained Saint Mary Goretti in the hour of her martyrdom, granting her the physical and spiritual fortitude to endure unspeakable suffering for the sake of purity, grant me through her intercession the grace to face my own trials with the same holy bravery. I confess that I am often weak in the face of difficulty, that I complain when life is hard, and that I lack the courage to stand firm when the pressures of the world, the flesh, and the devil conspire against me. Saint Mary Goretti, an eleven-year-old peasant girl who showed more courage in her final agony than many adults show in their entire lives, teaches me that the strength to endure comes not from human resources but from the grace of God working in a soul that is surrendered to His will. Grant me the grace to face every trial — whether persecution, sickness, loss, or temptation — with the confidence that God will never allow me to be tested beyond my capacity to bear it. Help me to remember that the martyrs were not superhuman but ordinary people who relied on extraordinary grace, and that the same grace is available to me if I will only ask for it. Amen.`,
  },
  {
    id: "smg-np-4",
    novenaId: "novenas-saint-mary-goretti",
    title: "Day 4 — Youth and Holiness",
    category: "novenas",
    day: 4,
    intention: "For the young people of the Church",
    text: `O Lord Jesus Christ, who called Saint Mary Goretti to sanctity at a tender age and who desires that all the young people of the Church follow her example of virtue, grant me through her intercession the grace to live my youth — or the memory of my youth — in a manner that is pleasing to You. I pray for all the young people of the world, especially those who are lost in the darkness of sin, addicted to substances, enslaved by technology, and seduced by the false promises of a culture that glorifies pleasure and rejects moral truth. Saint Mary Goretti, who was barely into her second decade when she won the crown of martyrdom, proves that holiness is possible at any age and that the young are not exempt from the call to sainthood. Grant that the example of this remarkable young saint may inspire a generation of Catholic youth to embrace purity, to reject the lies of the culture of death, and to pursue with passion the holiness that is their baptismal calling. May the intercession of Saint Mary Goretti protect all young people from the snares of the evil one and lead them safely to the arms of the Good Shepherd. Amen.`,
  },
  {
    id: "smg-np-5",
    novenaId: "novenas-saint-mary-goretti",
    title: "Day 5 — The Sacrament of Confession",
    category: "novenas",
    day: 5,
    intention: "To approach Confession with faith and humility",
    text: `O Merciful Father, who instituted the Sacrament of Reconciliation as the ordinary means of obtaining forgiveness for sins committed after Baptism, grant me through the intercession of Saint Mary Goretti the grace to approach this holy sacrament with sincere faith, genuine contrition, and humble confidence in Your mercy. I confess that I have avoided Confession, that I have been afraid to reveal my sins to the priest, and that I have not always experienced the profound healing and peace that this sacrament offers. Saint Mary Goretti, whose forgiveness of her attacker led to his conversion and his eventual entry into religious life, demonstrates the power of grace to transform even the most sinful soul. Grant me the courage to examine my conscience thoroughly, to confess my sins without minimizing or excusing them, to perform the penance assigned with care, and to resolve firmly to avoid the occasions of sin in the future. Help me to understand that Confession is not a punishment but a gift, not a source of shame but of healing, and that in the confessional I meet the merciful Christ who takes away the burden of my guilt and restores my soul to the freedom of grace. Amen.`,
  },
  {
    id: "smg-np-6",
    novenaId: "novenas-saint-mary-goretti",
    title: "Day 6 — The Family and Domestic Life",
    category: "novenas",
    day: 6,
    intention: "To sanctify family life",
    text: `O Holy Family of Nazareth — Jesus, Mary, and Joseph — who blessed the humble household of the Goretti family with the presence of Your love, grant me through the intercession of Saint Mary Goretti the grace to sanctify my own family life through the practice of virtue and the faithful fulfillment of my duties. I confess that I have often neglected the spiritual welfare of my family, that I have failed to pray with and for my loved ones, and that I have not always set a good example of Christian living in my home. Saint Mary Goretti, who grew up in a poor peasant family, who helped her mother raise her younger siblings after her father's death, and who fulfilled her domestic duties with diligence and love, teaches me that holiness begins in the home and that the ordinary work of family life can become a school of sanctity. Grant me the grace to love my family with the same selfless devotion that characterized Saint Mary's love for her mother and siblings, to pray for them daily, to forgive their faults, and to lead them by my example toward the God who is the source of all love and all grace. Amen.`,
  },
  {
    id: "smg-np-7",
    novenaId: "novenas-saint-mary-goretti",
    title: "Day 7 — Overcoming Temptation",
    category: "novenas",
    day: 7,
    intention: "To resist the attacks of the evil one",
    text: `O Lord Jesus Christ, who conquered the temptations of the devil in the wilderness and who promises victory to those who fight under the banner of the Cross, grant me through the intercession of Saint Mary Goretti the grace to resist temptation with courage and determination. I confess that I have often succumbed to the enticements of the flesh, the allurements of the world, and the deceptions of the devil, and that I have not always fled from the near occasions of sin as the Church exhorts. Saint Mary Goretti, who faced the most terrible temptation at the moment of her attack and who relied solely on the grace of God to sustain her, teaches me that no temptation is insurmountable when one is armed with prayer, sacramental grace, and a firm resolution to avoid sin at all costs. Grant me the grace to be vigilant in watching for the snares of the enemy, to flee immediately from any situation that arouses disordered desire, and to call upon the name of Jesus and the intercession of the Blessed Virgin Mary the moment I feel the pull of temptation. Help me to understand that the devil is a liar and a deceiver who promises freedom but delivers slavery, and that true liberty is found only in obedience to the law of God. Amen.`,
  },
  {
    id: "smg-np-8",
    novenaId: "novenas-saint-mary-goretti",
    title: "Day 8 — Conversion of Sinners",
    category: "novenas",
    day: 8,
    intention: "For the conversion of those who live in sin",
    text: `O God of infinite mercy, who converted the murderer of Saint Mary Goretti and brought him to the state of grace through the power of her forgiveness, grant me through her intercession the grace to pray earnestly for the conversion of sinners, especially those who have committed grave crimes against God and neighbor. I confess that I have often given up on certain people, believing them to be beyond redemption, and that I have failed to pray with sufficient fervor for those who live in the darkness of mortal sin. Saint Mary Goretti, who forgave Alessandro Serenelli and who appeared to him in prison to bring him the assurance of God's mercy, teaches me that no sin is so great as to place it beyond the reach of divine grace, and that the prayer of the just has the power to convert even the most hardened criminal. Grant me the grace to believe in the possibility of conversion for every sinner, to pray for them without ceasing, to offer sacrifices for their return to God, and to trust that the same God who converted Saul on the road to Damascus can transform any heart, no matter how cold or resistant it may appear. May the intercession of Saint Mary Goretti bring light to those who walk in darkness and hope to those who have lost all sense of God's love. Amen.`,
  },
  {
    id: "smg-np-9",
    novenaId: "novenas-saint-mary-goretti",
    title: "Day 9 — Eternal Reward for the Pure",
    category: "novenas",
    day: 9,
    intention: "To persevere in purity for the glory of heaven",
    text: `O God of eternal glory, who crowned Saint Mary Goretti with the martyr's palm and admitted her into the heavenly paradise on the very day of her death, grant me through her intercession the grace to persevere in purity, in faith, and in charity until the day of my death, when I hope to see You face to face. I believe that the pure of heart will see God, and I trust that the same God who sustained Saint Mary in her final agony will sustain me in my own journey toward heaven. Saint Mary Goretti, who at the age of eleven beheld the face of Christ and who now enjoys eternal happiness in the presence of the Blessed Trinity, intercede for me that I may live each day with the awareness that I am destined for eternal life, and that the choices I make in this world will determine my destiny in the next. Grant me the grace to keep my eyes fixed on the heavenly prize, to endure the trials of this life with patience, and to run the race to the finish with perseverance. May the hope of eternal reward strengthen me in my daily battle against sin, and may the intercession of Saint Mary Goretti accompany me at every step of my pilgrimage until I arrive at the gates of paradise, where together we shall praise the Father, the Son, and the Holy Spirit for all eternity. Amen.`,
  },
];
